function useView(id){const p={...referenceViews[id]};if(id.startsWith('deer-')){p.x=state.deer.x+(id==='deer-front'?5.5:id==='deer-back'?-5.5:0);p.z=state.deer.z+(id==='deer-side'?-5.5:0);}if(id==='bird'){p.x=state.bird.x+1.1;p.z=state.bird.z+2.2;}observer.x=p.x;observer.z=p.z;let target=typeof p.target==='function'?p.target():p.target;const plantViews={woodruff:'galium_odoratum',nettle:'urtica_dioica','salt-shrub':'halimione_portulacoides','salt-segments':'salicornia_europaea','salt-grass':'sporobolus_anglicus'};if(plantViews[id]){const found=state.plants.filter(q=>q.taxon===plantViews[id]).sort((a,b)=>Math.hypot(a.x-target[0],a.z-target[2])-Math.hypot(b.x-target[0],b.z-target[2]))[0];p.x=found.x+2.2;p.z=found.z+1.8;observer.x=p.x;observer.z=p.z;target=[found.x,found.y+found.size*.55,found.z];}const dx=target[0]-p.x,dz=target[2]-p.z;observer.yaw=Math.atan2(-dx,-dz);observer.pitch=Math.atan2(target[1]-walkingHeight(p.x,p.z)-1.67,Math.hypot(dx,dz));if(tool)setTool(tool);invalidate();close();}
