function showGuide(){panel(`<span class="eyebrow">TAFEL AM WALDSTART</span><h2>Willkommen im Rangerteam.</h2><p>${escape(COMPACT_GUIDE)}</p><p>Der Wald lebt von Streu, Schatten und kleinen Lichtungen. Das Dorf erreichst du vom Start über den kurzen Weg nach Osten. Der längere Beobachtungsweg führt durch den Wald und anschließend über den Deich.</p><button id="guide-close">Zurück in die Landschaft</button>`);$('guide-close').onclick=close;}
